// ============================================
// SURAH 4 - AN-NISA (The Women) - COMPLETE 176 VERSES
// ============================================

MIROIR["4:1"] = {
  reference: "4:1",
  theme: ["présence", "méditation", "gratitude"],
  emotion: "Unité reconnaissante",
  difficulty: "débutant",
  relatedNames: ["Al-Khaliq", "Al-Wahid"],
  mirrorVersion: `« Ô hommes ! Craignez votre Seigneur qui vous a créés d'un seul être et a créé de celui-ci son épouse, et qui a fait naître de ces deux-là une multitude d'hommes et de femmes. » Le miroir me ramène à l'origine unique de l'humanité. Nous sommes tous frères et sœurs — pas métaphoriquement, mais littéralement. Adam et Ève sont les parents de tous. Cette unité d'origine devrait fonder une fraternité universelle. Les divisions que nous créons — races, nations, classes — sont des illusions qui nous éloignent de notre vérité première.`,
  reflection: `L'humanité est une famille. Les différences sont superficielles, l'origine est commune. La taqwa nous relie à cette unité perdue.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Nafsin wahida » — une seule âme. L'humanité entière vient d'une source unique, Adam, et son épouse Hawwa." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment je traite mes frères et sœurs humains ? Avec le respect dû à la famille ? Le miroir interroge mes divisions." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Les divisions que je considère naturelles — race, nation, classe — sont des constructions humaines, pas divines. L'unité est la vérité." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "L'univers entier manifeste l'unité dans la diversité. La création est une, multiple dans ses expressions." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui voit l'unité de l'humanité voit l'unité de la création. La fraternité est la vision juste." }
  ],
  munajat: `Ya Khaliq, Tu nous as créés d'un seul. Fais que je voie en chaque être humain mon frère ou ma sœur. Unifie mon cœur avec Ta création.`
};

MIROIR["4:2"] = {
  reference: "4:2",
  theme: ["justice", "confiance", "méditation"],
  emotion: "Responsabilité protectrice",
  difficulty: "débutant",
  relatedNames: ["Al-Hakam", "Al-Adl"],
  mirrorVersion: `« Et rendez aux orphelins leurs biens. Ne substituez pas de mauvaises choses aux bonnes. » Le miroir me place devant la vulnérabilité des orphelins et la tentation de profiter de leur faiblesse. Ce verset établit un principe : ce qui appartient à autrui doit être préservé, surtout quand autrui ne peut pas se défendre. La tentation de substituer « le mauvais au bon » révèle notre capacité à justifier l'injustice quand personne ne regarde. Mais Allah regarde toujours.`,
  reflection: `La justice envers les vulnérables est le test de notre intégrité. Ce que nous faisons dans l'ombre révèle notre vrai caractère.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Le verset protège les biens des orphelins, ceux qui n'ont pas de défenseurs naturels." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment je traite ceux qui dépendent de moi ? Suis-je digne de confiance quand personne ne surveille ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "L'orphelin que je pourrais exploiter aujourd'hui était peut-être moi hier, ou sera moi demain dans une autre forme." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Chaque créature vulnérable dans l'univers est sous la protection divine. Nous sommes les gardiens les uns des autres." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "L'intégrité se mesure dans l'obscurité. Ce que nous faisons quand personne ne voit définit qui nous sommes vraiment." }
  ],
  munajat: `Ya Hakam, Tu me demandes d'être juste envers les vulnérables. Purifie mon cœur de l'avidité. Fais que je sois un gardien fidèle.`
};

MIROIR["4:3"] = {
  reference: "4:3",
  theme: ["justice", "méditation", "patience"],
  emotion: "Responsabilité mesurée",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Adl", "Al-Hakim"],
  mirrorVersion: `« Si vous craignez d'être injustes envers les orphelins, épousez alors ce qui vous plaît parmi les femmes, de deux, trois ou quatre. Mais si vous craignez de ne pas être équitables, alors une seule. » Le miroir me révèle une logique surprenante : la polygamie est présentée non comme un droit mais comme une restriction. Le verset commence par la crainte d'injustice envers les orphelins et aboutit à la recommandation d'une seule épouse si l'équité est impossible. La condition « si vous craignez de ne pas être équitables » est la clé.`,
  reflection: `La permission n'est pas une obligation. L'équité est la condition. Le Coran protège en posant des limites strictes.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Une permission encadrée par une condition impossible à remplir parfaitement : l'équité absolue." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Quand je désire quelque chose, est-ce que je vérifie si je peux être juste ? Ou est-ce que je suis guidé par le désir seul ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Le verset qui semble ouvrir une porte la referme en réalité par l'exigence d'équité parfaite." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La justice dans les relations humaines est l'équilibre qui maintient l'harmonie sociale. Sans elle, le chaos." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "La vraie justice est impossible sans Dieu. Seul Lui est parfaitement équitable. Nous aspirons à cette perfection." }
  ],
  munajat: `Ya 'Adl, la justice parfaite m'échappe. Guide-moi vers l'équité dans toutes mes relations. Que mes désirs ne dominent jamais ma conscience.`
};

MIROIR["4:4"] = {
  reference: "4:4",
  theme: ["amour", "méditation", "détachement"],
  emotion: "Générosité honorable",
  difficulty: "débutant",
  relatedNames: ["Al-Karim", "Al-Ghani"],
  mirrorVersion: `« Et donnez aux femmes leurs dots de bonne grâce. » Le miroir m'invite à réfléchir sur le don dans le mariage. La dot n'est pas un prix d'achat — c'est un cadeau, un honneur, une reconnaissance. « De bonne grâce » signifie sans contrainte, sans regret, avec générosité. Ce don initial pose le ton de la relation : le mariage commence par le don, pas par la prise. L'homme qui donne sa dot à contrecoeur a déjà manqué l'esprit de l'union.`,
  reflection: `Le mariage commence par le don. La qualité du commencement influence tout ce qui suit.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "La dot (mahr) est un droit de la femme, donné librement, sans contrainte." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment je donne ? De bon cœur ou à contrecoeur ? Le miroir mesure ma générosité." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ce que je donne de bon cœur me revient multiplié. Ce que je garde par avarice me fuit." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "L'univers entier fonctionne par le don. Le soleil donne sa lumière, la terre donne sa nourriture." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le don pur est celui qui oublie qu'il donne. Il devient aussi naturel que la respiration." }
  ],
  munajat: `Ya Karim, Tu es le plus généreux. Apprends-moi à donner de bon cœur, à honorer ceux que Tu m'as donné d'aimer.`
};

MIROIR["4:5"] = {
  reference: "4:5",
  theme: ["confiance", "méditation", "patience"],
  emotion: "Sagesse protectrice",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Hakim", "Al-Hafiz"],
  mirrorVersion: `« Ne confiez pas aux incapables les biens qu'Allah a confiés à votre garde. » Le miroir me place devant une responsabilité : les biens dont nous sommes dépositaires doivent être gérés avec sagesse. Confier à qui ne peut pas gérer n'est pas de la générosité — c'est de l'imprudence. Le verset protège à la fois le bien et la personne : l'incapable qui reçoit trop peut se perdre. La vraie sagesse est de donner selon la capacité de recevoir.`,
  reflection: `La gestion responsable n'est pas de l'avarice — c'est de la protection. Tout don doit être mesuré à l'aune de la capacité.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Les biens sont un dépôt divin (amanah). Nous en sommes les gardiens, pas les propriétaires absolus." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Qu'est-ce qui m'a été confié ? Argents, responsabilités, personnes ? Suis-je un bon gardien ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ce que je garde par sagesse protège. Ce que je donne par imprudence peut détruire." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Chaque créature reçoit selon sa capacité. La nature enseigne la mesure par son exemple." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le bon gestionnaire est celui qui sait quand garder et quand lâcher. La sagesse est dans le timing." }
  ],
  munajat: `Ya Hakim, Tu m'as confié des biens et des responsabilités. Donne-moi la sagesse de les gérer selon Ta volonté, ni par avarice ni par imprudence.`
};

MIROIR["4:6"] = {
  reference: "4:6",
  theme: ["méditation", "patience", "confiance"],
  emotion: "Croissance surveillée",
  difficulty: "débutant",
  relatedNames: ["Al-Rashid", "Al-Hakim"],
  mirrorVersion: `« Et éprouvez les orphelins jusqu'à ce qu'ils atteignent l'âge du mariage. Si vous percevez en eux maturité et droiture, remettez-leur leurs biens. » Le miroir m'enseigne la pédagogie divine : la confiance se construit progressivement. On ne donne pas tout à l'enfant — on le teste, on l'éprouve, on observe sa croissance. Et quand la maturité arrive, on rend ce qui lui appartient. Ce n'est pas du contrôle possessif — c'est de l'éducation protectrice.`,
  reflection: `La vraie éducation est un passage progressif de la dépendance à l'autonomie. Le test n'est pas une méfiance — c'est une préparation.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Le verset établit une pédagogie : tester, observer, puis libérer quand la maturité est là." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment je gère ceux qui dépendent de moi ? Est-ce que je prépare leur autonomie ou je maintiens leur dépendance ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Celui qui ne teste pas ne fait pas confiance. Celui qui ne libère pas ne laisse pas grandir." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Dans la nature, le jeune animal est testé par la vie. Seuls les humains peuvent retarder artificiellement la maturité." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le plus dur pour le gardien est de lâcher prise au bon moment. Trop tôt, c'est l'abandon. Trop tard, c'est l'étouffement." }
  ],
  munajat: `Ya Rashid, Tu es le Guide vers la maturité. Apprends-moi à éduquer, à tester avec bienveillance, et à libérer quand le temps est venu.`
};

MIROIR["4:7"] = {
  reference: "4:7",
  theme: ["justice", "méditation", "gratitude"],
  emotion: "Partage équitable",
  difficulty: "débutant",
  relatedNames: ["Al-Adl", "Al-Wasi'"],
  mirrorVersion: `« Aux hommes revient une part de ce qu'ont laissé les père et mère et les proches. Aux femmes revient une part de ce qu'ont laissé les père et mère et les proches. » Le miroir me montre une révolution silencieuse : à une époque où les femmes n'héritaient pas, le Coran leur donne une part. Pas « aux hommes seulement » mais « aux hommes ET aux femmes ». Le verset établit un principe d'inclusion qui était en avance sur son temps. L'héritage n'est pas un privilège masculin — c'est un droit universel.`,
  reflection: `La justice divine inclut ceux que les sociétés excluent. Les droits des femmes sont établis par le Coran il y a 1400 ans.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Le verset accorde l'héritage aux femmes à une époque où elles en étaient exclues." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Comment je partage ? Est-ce que je donne à chacun son droit ou est-ce que je privilégie arbitrairement ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ce qui semble « normal » dans une société peut être injustice aux yeux de Dieu." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La distribution équitable des ressources maintient l'équilibre social. L'injustice crée les fissures qui détruisent les familles." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "L'héritage n'est pas un dû — c'est une confiance qui passe. Le vrai héritage est spirituel : la foi, les valeurs, l'exemple." }
  ],
  munajat: `Ya 'Adl, Tu as établi la justice pour tous. Aide-moi à respecter les droits de chacun, à ne pas m'approprier ce qui appartient à d'autres.`
};

MIROIR["4:8"] = {
  reference: "4:8",
  theme: ["amour", "gratitude", "méditation"],
  emotion: "Générosité opportune",
  difficulty: "débutant",
  relatedNames: ["Ar-Razzaq", "Al-Karim"],
  mirrorVersion: `« Et lorsque les proches, les orphelins et les pauvres assistent au partage, faites-en une part pour eux. » Le miroir m'invite à élargir le cercle du partage. L'héritage ne concerne pas seulement les héritiers directs — il doit inclure les présents dans le besoin. Ce verset transforme un moment de division potentielle en occasion de générosité. Les pauvres qui assistent au partage ne doivent pas repartir les mains vides.`,
  reflection: `La générosité n'attend pas le moment parfait — elle crée le moment. Chaque occasion de partage est une occasion de donner.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Une prescription de générosité au moment même où l'on pourrait être le plus centré sur soi." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Quand je reçois, est-ce que je pense à ceux qui sont autour de moi dans le besoin ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Le moment où je reçois le plus est le moment où je dois donner le plus. La réception et le don sont liés." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Dans l'écosystème, celui qui mange invite les autres à partager. L'isolement dans l'abondance n'existe pas dans la nature." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "La vraie abondance est celle qui se partage. Ce qui est gardé seul se corrompt. Ce qui est donné ensemble grandit." }
  ],
  munajat: `Ya Razzaq, Tu es le Pourvoyeur de tous. Quand je reçois, rappelle-moi ceux qui ont moins. Fais de moi un canal de Ta générosité.`
};

MIROIR["4:9"] = {
  reference: "4:9",
  theme: ["méditation", "confiance", "empathie"],
  emotion: "Sollicitude anticipatrice",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Wali", "Al-Hafiz"],
  mirrorVersion: `« Que ceux qui laisseraient après eux des enfants en bas âge craignent pour eux. Qu'ils craignent Allah et qu'ils parlent avec droiture. » Le miroir me place dans les souliers de l'orphelin : imaginez que vous mouriez et laissiez des enfants faibles. Comment voudriez-vous qu'on les traite ? Cette empathie inversée doit guider notre conduite envers les orphelins d'aujourd'hui. Ce que nous voulons pour nos enfants, faisons-le pour les enfants des autres.`,
  reflection: `L'empathie est le pont entre soi et autrui. Traite les autres comme tu voudrais que tes propres enfants soient traités.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Une projection empathique : imaginez vos propres enfants orphelins. Cette image doit guider votre action." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Si je mourais aujourd'hui, comment voudrais-je qu'on traite mes enfants ? Est-ce que je traite les orphelins ainsi ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "L'orphelin que je néglige pourrait être mon enfant dans une autre vie. La mort nous égaux tous." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Dans la nature, les petits sans protection sont adoptés par le groupe. L'instinct de protection transcende les liens du sang." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui protège l'orphelin protège sa propre descendance dans l'invisible. La bienveillance crée des liens que la mort ne rompt pas." }
  ],
  munajat: `Ya Wali, Tu es le Protecteur des orphelins. Ouvre mon cœur à la peur que je ressentirais pour mes propres enfants. Fais que je sois un tuteur bienveillant.`
};

MIROIR["4:10"] = {
  reference: "4:10",
  theme: ["justice", "force", "méditation"],
  emotion: "Avertissement solennel",
  difficulty: "débutant",
  relatedNames: ["Al-Jabbar", "Al-Muntaqim"],
  mirrorVersion: `« Ceux qui mangent injustement les biens des orphelins mangent du feu dans leurs ventres. » Le miroir m'offre une image terrifiante : l'injustice envers les vulnérables consume l'injuste de l'intérieur. Ce n'est pas seulement une punition dans l'au-delà — c'est une vérité psychologique. Celui qui exploite les faibles se détruit intérieurement. Le feu est déjà là, dans le ventre, dans la conscience qui se corrompt. L'injustice ne reste jamais sans conséquence.`,
  reflection: `L'injustice envers les vulnérables est la pire des injustices. Le châtiment commence dans cette vie, par la corruption du cœur.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Une image frappante : manger du feu. L'injustice est une consommation qui consume." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Qu'est-ce que je « mange » qui ne m'appartient pas ? Quelles injustices nourrissent ma vie ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ce que je prends injustement aux autres, je le prends à moi-même dans l'autre monde." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "L'univers maintient l'équilibre. Toute prise injuste crée une dette qui sera collectée." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le feu de l'enfer commence ici par le remords. La conscience qui s'accuse crée son propre châtiment." }
  ],
  munajat: `Ya Jabbar, Tu es le Redresseur des torts. Préserve-moi de l'injustice envers les vulnérables. Que mon gain ne soit jamais la perte des autres.`
};

MIROIR["4:11"] = {
  reference: "4:11",
  theme: ["justice", "méditation", "confiance"],
  emotion: "Ordre équitable",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Adl", "Al-Hakim"],
  mirrorVersion: `« Allah vous commande au sujet de vos enfants : au fils, une part équivalente à celle de deux filles. » Le miroir m'invite à comprendre une sagesse souvent mal interprétée. La différence de parts s'explique par les responsabilités financières : l'homme doit subvenir aux besoins de la famille, la femme garde son héritage pour elle. La « demi-part » de la femme n'est pas une dévalorisation — c'est une protection économique. Elle reçoit moins mais garde tout. Il reçoit plus mais dépense pour les autres.`,
  reflection: `La justice divine tient compte des responsabilités. Les parts différentes reflètent les charges différentes.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "Des règles précises d'héritage qui établissent des parts selon les liens familiaux et les responsabilités." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que j'accepte les lois divines même quand je ne comprends pas immédiatement leur sagesse ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Celui qui reçoit plus porte plus. L'abondance sans responsabilité devient corruption." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Dans l'équilibre naturel, chaque élément reçoit selon sa fonction. La nature ne connaît pas l'égalité mécanique mais l'harmonie fonctionnelle." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "L'héritage matériel est limité. L'héritage spirituel — la foi, les valeurs, le bon nom — n'a pas de limites et se partage également." }
  ],
  munajat: `Ya Hakim, Ta sagesse dépasse ma compréhension. Aide-moi à accepter Tes lois avec confiance et à voir la justice dans ce qui semble inégal.`
};

